def cc(n):
    s = ''
    while n != 0:
        s = str(n % 5) + s
        n //= 5
    return s
def f(n):
    s = cc(n)
    if sum(list(map(int,list(s)))) % 5 == 0:
        s = s.replace('1','*').replace('0','1').replace('*','0')
        s += '14'
    else:
        s += '33'
        s = '44' + s[2:]
    return int(s,5)
minR = float('inf')
ans = 0
for i in range(1,100000):
    if f(i) > 370:
        if f(i) < minR:
            minR = f(i)
            ans = i
print(ans)
